text:
:host,
:root {
  --button-height: 2.2em;
  --border-color: color-mix(in srgb, currentColor 46%, transparent);
  --button-border-radius: 3px;
  --button-border-color-hover: color-mix(in srgb, currentColor 17%, transparent);
  --in-content-deemphasized-text: color-mix(in srgb, currentColor 60%, transparent);
  --size-sidebar: auto;
  --menu-item-margin: 0 3px;
  --panel-border-radius: 9px;

  @media not (forced-colors) {
    --background-color-box-info: light-dark(var(--layout-background-1), var(--layout-background-2));
    --border-color-box-info: light-dark(var(--layout-border-0), transparent);
    --color-accent-primary-selected-unfocused: light-dark(var(--color-gray-20), rgba(249, 249, 250, 0.05));
    --color-accent-primary-selected: var(--selected-item-color);
    --text-color-accent-primary-selected: var(--selected-item-text-color);
    --in-content-focus-outline-color: AccentColor;
    --in-content-accent-color: AccentColor;
  }

  @media (forced-colors) {
    --background-color-box-info: transparent;
    --border-color-box-info: currentColor;
    --border-color: -moz-DialogText;
    --in-content-accent-color: SelectedItem;
  }
